import { useEffect, useState } from "react";
import { Activity, CheckCircle, Download, Eye, FileImage, Flame, History, Home, Image as ImageIcon, Maximize2, RotateCcw, ScanLine, Search, SlidersHorizontal, X, ZoomIn } from "lucide-react";
import { Link, useLocation, useNavigate, useParams } from "react-router-dom";
import { getPatient, renderScanPreview, renderStoredScanPreview } from "../../api/medvisionApi";
import { downloadDiagnosticPdf } from "./diagnosticReportPdf";
import "./DiagnosticResults.css";
import "./DiagnosticReportPreview.css";

export default function DiagnosticResults() {
  const navigate = useNavigate();
  const location = useLocation();
  const { patientId } = useParams();
  const [patientData, setPatientData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [activeView, setActiveView] = useState("heatmap");
  const [zoomLevel, setZoomLevel] = useState(1);
  const [brightness, setBrightness] = useState(100);
  const [contrast, setContrast] = useState(100);
  const [showAdjust, setShowAdjust] = useState(false);
  const [showReportPreview, setShowReportPreview] = useState(false);
  const [localImageUrl, setLocalImageUrl] = useState("");
  const [decodedOriginalUrl, setDecodedOriginalUrl] = useState("");
  const [originalImageLoading, setOriginalImageLoading] = useState(false);
  const [originalImageError, setOriginalImageError] = useState("");
  const [reportError, setReportError] = useState("");

  useEffect(() => {
    let cancelled = false;
    const loadPatient = async () => {
      if (patientId) {
        try {
          const patient = await getPatient(patientId);
          if (!cancelled) setPatientData(patient);
        } catch (error) {
          console.error("Unable to load saved patient:", error);
          if (!cancelled) {
            const fallback = location.state?.patientData || (location.state?.formData
              ? {
                ...location.state.formData,
                aiFindings: Array.isArray(location.state.aiData) ? location.state.aiData : [location.state.aiData].filter(Boolean),
                heatmapUrl: location.state.heatmapUrl
              }
              : null);
            setPatientData(fallback);
          }
        } finally {
          if (!cancelled) setLoading(false);
        }
        return;
      }
      if (location.state?.patientData) {
        setPatientData(location.state.patientData);
        setLoading(false);
      } else if (location.state?.aiData && location.state?.formData) {
        const findings = Array.isArray(location.state.aiData) ? location.state.aiData : [location.state.aiData];
        setPatientData({ ...location.state.formData, aiFindings: findings, heatmapUrl: location.state.heatmapUrl });
        setLoading(false);
      } else navigate("/");
    };
    loadPatient();
    return () => { cancelled = true; };
  }, [patientId, location.state, navigate]);

  useEffect(() => {
    let cancelled = false;
    let objectUrl = "";
    setLocalImageUrl("");
    setDecodedOriginalUrl("");
    setOriginalImageError("");
    const file = patientData?.image;
    const imageUrl = patientData?.imageUrl;
    if (!file && !imageUrl) {
      setOriginalImageLoading(false);
      return undefined;
    }
    const extension = file?.name?.split(".").pop()?.toLowerCase();
    const isDicom = patientData?.sourceFormat === "dicom" || patientData?.dicom || ["dcm", "dicom"].includes(extension) || /\.(dcm|dicom)(\?|$)/i.test(imageUrl || "");
    if (isDicom) {
      setOriginalImageLoading(true);
      const previewPromise = file ? renderScanPreview(file) : renderStoredScanPreview(imageUrl);
      previewPromise.then((previewUrl) => {
        if (!cancelled) setDecodedOriginalUrl(previewUrl);
      }).catch((error) => {
        if (!cancelled) setOriginalImageError(error.message || "Could not render the original DICOM image.");
      }).finally(() => {
        if (!cancelled) setOriginalImageLoading(false);
      });
      return () => { cancelled = true; };
    }
    if (!file) {
      setOriginalImageLoading(false);
      return undefined;
    }
    objectUrl = URL.createObjectURL(file);
    setLocalImageUrl(objectUrl);
    setOriginalImageLoading(false);
    return () => {
      cancelled = true;
      URL.revokeObjectURL(objectUrl);
    };
  }, [patientData?.image, patientData?.imageUrl, patientData?.sourceFormat, patientData?.dicom]);

  const formatDate = (value) => {
    if (!value) return "N/A";
    if (typeof value === "string") {
      const date = new Date(value);
      return Number.isNaN(date.getTime()) ? value : date.toISOString().slice(0, 10);
    }
    return value;
  };

  if (loading || !patientData) return <div className="diagnostic-loading">Loading results…</div>;

  const isDicomSource = patientData.sourceFormat === "dicom" || Boolean(patientData.dicom) || /\.(dcm|dicom)(\?|$)/i.test(patientData.image?.name || patientData.imageUrl || "");
  const originalSrc = decodedOriginalUrl || localImageUrl || (isDicomSource ? null : patientData.imageUrl) || null;
  const hasHeatmap = Boolean(patientData.heatmapUrl);
  const showingHeatmap = activeView === "heatmap" && hasHeatmap;
  const activeSrc = showingHeatmap ? patientData.heatmapUrl : originalSrc;
  const findings = patientData.aiFindings || [];
  const notableFindings = findings.filter((finding) => finding.name !== "No Significant Findings");
  const topFinding = notableFindings[0];
  const reportNumber = (() => {
    const existingDigits = String(patientData.reportNumber || "").replace(/\D/g, "");
    if (existingDigits) return existingDigits.slice(-3).padStart(3, "0");
    const source = `${patientData.patientId || patientData.id || "report"}-${formatDate(patientData.date)}`;
    const numericHash = Array.from(source).reduce((hash, character) => ((hash * 31) + character.charCodeAt(0)) % 900, 0);
    return String(numericHash + 100);
  })();
  const diseaseDescriptions = {
    Atelectasis: "A portion of the lung appears less aerated or partially collapsed. This can have several causes and needs interpretation with the full image and clinical context.",
    Cardiomegaly: "The heart silhouette appears larger than expected on this image. Positioning and technique can affect its apparent size, so clinical review is needed.",
    Consolidation: "An area of lung appears denser than expected, which can occur when air spaces contain fluid or other material. This appearance is not specific to one cause.",
    Edema: "The image may show increased fluid-related opacity in the lungs. A clinician should assess this alongside symptoms and other findings.",
    Effusion: "The model marked a possible fluid collection in the space around a lung. A clinician should verify its presence and significance on the scan.",
    "Pleural Effusion": "The model marked a possible fluid collection in the space around a lung. A clinician should verify its presence and significance on the scan.",
    Pneumonia: "The image may show a lung opacity that can be seen with pneumonia, but imaging alone does not establish the cause. Clinical assessment is required.",
    Pneumothorax: "The model marked a possible collection of air outside a lung. This finding requires prompt professional review to confirm and assess.",
    Nodule: "A small, localized opacity may be present in the lung. Many causes are possible, and further assessment may be needed to characterize it.",
    Mass: "A larger localized opacity may be present in the lung. This image finding has multiple possible causes and requires clinician assessment.",
    Fibrosis: "The model marked a possible pattern of lung scarring. The finding should be confirmed and interpreted with prior imaging and clinical history.",
    "Pleural Thickening": "The lining around the lung may appear thickened. This appearance can have different causes and should be reviewed by a clinician.",
    "Lung Opacity": "An area of the lung appears denser than expected. Opacity is a general imaging description, not a diagnosis, and has several possible causes.",
    "No Finding": "The model did not identify a target abnormality. This does not rule out disease; a qualified clinician should review the complete study."
  };
  const clinicalDescription = (finding) => finding.description || diseaseDescriptions[finding.name] || `The AI model marked ${finding.name} as a possible imaging finding. This label describes a model observation, not a confirmed diagnosis; a qualified clinician should interpret it alongside the scan and the patient's clinical history.`;
  const reportFindings = notableFindings.map((finding) => ({
    disease: finding.name,
    confidence: finding.probability == null ? "N/A" : `${finding.probability}%`,
    description: clinicalDescription(finding)
  }));
  const downloadReport = async () => {
    setReportError("");
    try {
      await downloadDiagnosticPdf({
        patientName: patientData.name,
        patientId: patientData.patientId,
        gender: patientData.gender,
        age: patientData.age,
        reportNumber,
        serviceProvider: "MedVision AI",
        scanType: patientData.scanType || "Chest X-ray",
        processedDate: formatDate(patientData.date),
        originalImage: originalSrc,
        heatmapImage: patientData.heatmapUrl || "",
        findings: reportFindings
      });
    } catch (error) {
      console.error("Unable to generate report PDF:", error);
      setReportError("The PDF could not load both scan images. Check their availability and try again.");
    }
  };

  return (
    <main className="diagnostic-workstation">
      <header className="diagnostic-topbar">
        <Link to="/" className="diagnostic-brand"><span className="brand-mark"><Activity size={15} /></span><span>MedVision <b>INSIGHT</b><small> CXR</small></span></Link>
        <div className="topbar-center"><Link to="/">UPLOAD SCAN</Link><span className="topbar-divider" /><span className="topbar-current">DIAGNOSTIC ANALYSIS</span></div>
        <Link to="/consult" className="topbar-history"><History size={15} /> <span>Study History</span></Link>
      </header>

      <div className="diagnostic-body">
        <section className="scan-workspace" aria-label="Diagnostic image workspace">
          <div className="scan-toolbar">
            <div className="study-label"><span className="live-dot" /><span>{patientData.scanType || "Chest X-Ray"}</span><span className="study-separator">/</span><span>{formatDate(patientData.date)}</span></div>
            <div className="scan-tools">
              {hasHeatmap && <div className="view-switch" aria-label="Image view">
                <button className={showingHeatmap ? "selected" : ""} onClick={() => setActiveView("heatmap")}><Flame size={13} /> Heatmap</button>
                <button className={!showingHeatmap ? "selected" : ""} onClick={() => setActiveView("original")}><ImageIcon size={13} /> Original</button>
              </div>}
              <button className="icon-tool" title={`Zoom in (${Math.round(zoomLevel * 100)}%)`} onClick={() => setZoomLevel((current) => Math.min(3, Number((current + 0.25).toFixed(2))))}><ZoomIn size={16} /></button><button className={`icon-tool ${showAdjust ? "tool-active" : ""}`} title="Adjust image" onClick={() => setShowAdjust((current) => !current)}><SlidersHorizontal size={16} /></button><button className="icon-tool" title="Reset adjustments" onClick={() => { setBrightness(100); setContrast(100); }}><RotateCcw size={15} /></button><button className="icon-tool" title="Fit image" onClick={() => { setZoomLevel(1); setBrightness(100); setContrast(100); }}><Maximize2 size={15} /></button>
            </div>
          </div>
          {showAdjust && <div className="image-adjust-panel"><label>Brightness <input type="range" min="50" max="150" value={brightness} onChange={(event) => setBrightness(Number(event.target.value))} /><b>{brightness}%</b></label><label>Contrast <input type="range" min="50" max="180" value={contrast} onChange={(event) => setContrast(Number(event.target.value))} /><b>{contrast}%</b></label></div>}
          <div className="scan-stage">
            <div className="scan-image-frame">
              {activeSrc ? <img src={activeSrc} alt={showingHeatmap ? "AI analysis heatmap overlay" : "Uploaded diagnostic scan"} className="scan-image" style={{ transform: `scale(${zoomLevel})`, filter: `brightness(${brightness}%) contrast(${contrast}%)` }} /> : <div className="scan-empty"><FileImage size={42} /><span>{originalImageLoading ? "Rendering original DICOM image…" : originalImageError || "No image available for this study"}</span></div>}
              <div className="image-caption"><ScanLine size={13} /> {showingHeatmap ? "AI ATTENTION MAP" : "ORIGINAL IMAGE"}</div>
            </div>
            <div className="scan-side-note"><span>STUDY</span><b>{patientData.patientId || "—"}</b><span>PROCESSED</span><b>{formatDate(patientData.date)}</b></div>
          </div>
          <div className="scan-footer"><span><Activity size={12} /> MedVision AI · Clinical decision support</span><span>Review findings with clinical context</span></div>
        </section>

        <aside className="analysis-rail">
          <div className="rail-section rail-study">
            <div className="rail-heading"><span>STUDY OVERVIEW</span><button title="Search study"><Search size={14} /></button></div>
            <h1>{patientData.scanType || "Chest X-Ray"}</h1><p>{patientData.name || "Patient"} <i>·</i> {patientData.age || "—"} yrs <i>·</i> {patientData.gender || "—"}</p>
            <div className="study-meta"><span>Study date</span><b>{formatDate(patientData.date)}</b><span>Patient ID</span><b>{patientData.patientId || "—"}</b></div>
          </div>

          <div className="rail-section controls-section">
            <div className="rail-heading"><span>VIEW CONTROLS</span></div>
            <div className="control-label">IMAGE DISPLAY</div>
            <div className="display-control"><button className={showingHeatmap ? "active" : ""} onClick={() => setActiveView("heatmap")} disabled={!hasHeatmap}><Flame size={14} /> AI Overlay</button><button className={!showingHeatmap ? "active" : ""} onClick={() => setActiveView("original")}><ImageIcon size={14} /> Original</button></div>
            {showingHeatmap && <div className="overlay-legend"><span className="legend-gradient" /><div><span>Lower attention</span><span>Higher attention</span></div></div>}
          </div>

          <div className="rail-section results-section">
            <div className="rail-heading"><span>INSIGHT ANALYSIS</span><span className="ai-badge">AI</span></div>
            <div className="score-title"><span>Top finding</span></div>
            <div className="finding-primary">{topFinding?.name || "No significant findings"}</div>
            <div className="score-row"><span>Confidence</span><b>{topFinding?.probability != null ? `${topFinding.probability}%` : "—"}</b></div>
            <div className="score-track"><span style={{ width: `${Math.min(100, Math.max(0, Number(topFinding?.probability) || 0))}%`, background: topFinding?.color || "#21c7bd" }} /></div>
            {topFinding?.description && <p className="finding-description">{topFinding.description}</p>}
            <div className="finding-list">
              {findings.length ? findings.map((finding, index) => <div className="finding-row" key={`${finding.name}-${index}`}><span className="finding-dot" style={{ backgroundColor: finding.color || "#8497a9" }} /><span>{finding.name || "Unknown"}</span><b>{finding.probability != null ? `${finding.probability}%` : "—"}</b></div>) : <p className="muted-copy">No AI findings are available yet.</p>}
            </div>
          </div>

          <div className="rail-section recommendation-section">
            <div className="rail-heading"><span>RECOMMENDATIONS</span><CheckCircle size={14} /></div>
            {findings.length ? findings.map((finding, index) => <div className="recommendation" key={`rec-${index}`}><b>{finding.name || "Clinical review"}</b><p>{finding.recommendations?.length ? finding.recommendations.join(" ") : "Correlate with clinical presentation and review with a qualified clinician."}</p></div>) : <p className="muted-copy">No recommendations available.</p>}
          </div>
          <div className="rail-actions"><button className="report-button" onClick={() => setShowReportPreview(true)}><Eye size={15} /> Preview Report</button><Link to="/consult" className="history-link"><Home size={14} /> View study history</Link></div>
        </aside>
      </div>
      {showReportPreview && <div className="report-preview-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) setShowReportPreview(false); }}>
        <section className="report-preview-dialog" role="dialog" aria-modal="true" aria-labelledby="report-preview-title">
          <header className="report-preview-toolbar"><div><FileImage size={18} /><span>Report preview</span></div><button onClick={() => setShowReportPreview(false)} aria-label="Close report preview"><X size={20} /></button></header>
          <div className="report-preview-scroll"><article className="report-sheet">
            <h2 id="report-preview-title" className="diagnostic-report-heading">Diagnostic Report</h2>
            <div className="report-meta-grid"><div><small>Service provider</small><b>MedVision AI</b></div><div><small>Report number</small><b>{reportNumber}</b></div><div><small>Patient</small><b>{patientData.name || "Not provided"}</b></div><div><small>Patient ID</small><b>{patientData.patientId || "Not provided"}</b></div><div><small>Gender</small><b>{patientData.gender || "Not provided"}</b></div><div><small>Age</small><b>{patientData.age ? `${patientData.age} years` : "Not provided"}</b></div><div><small>Scan type</small><b>{patientData.scanType || "Medical imaging"}</b></div><div><small>Date processed</small><b>{formatDate(patientData.date)}</b></div></div>
            <h3 className="report-section-title">I &nbsp; Scan images</h3>
            <div className="report-images-grid"><figure><div>{originalSrc ? <img src={originalSrc} alt="Original diagnostic scan" /> : <span>Original image unavailable</span>}</div><figcaption>Original image</figcaption></figure><figure><div>{patientData.heatmapUrl ? <img src={patientData.heatmapUrl} alt="AI heatmap overlay" /> : <span>AI heatmap unavailable</span>}</div><figcaption>AI heatmap</figcaption></figure></div>
            <h3 className="report-section-title">II &nbsp; Diseases detected and confidence</h3>
            <table className="report-findings-table"><thead><tr><th>Disease</th><th>Confidence score</th></tr></thead><tbody>{reportFindings.length ? reportFindings.map((row, index) => <tr key={`${row.disease}-${index}`}><td>{row.disease}</td><td>{row.confidence}</td></tr>) : <tr><td>No significant findings detected</td><td>N/A</td></tr>}</tbody></table>
            <h3 className="report-section-title">III &nbsp; Clinical Validation</h3>
            <div className="report-validation-list">{reportFindings.length ? reportFindings.map((row, index) => <section key={`validation-${index}`}><h4>{row.disease}</h4><p>{row.description}</p></section>) : <p>No disease findings were identified for clinical validation.</p>}</div>
            <p className="report-disclaimer">AI-generated findings are intended to support qualified clinical review.</p>
          </article></div>
          <footer className="report-preview-footer">{reportError && <span className="report-error">{reportError}</span>}<button className="report-download-button" onClick={downloadReport}><Download size={16} /> Download PDF</button></footer>
        </section>
      </div>}
    </main>
  );
}
